"""Fresh SDK consumer staging and deterministic generated-output hashes."""

from __future__ import annotations

import hashlib
from pathlib import Path

from sqlite_sdk_consumer import ROOT, stage_consumer
from strict_generated_analyze import GENERATED_MARKER


def stage_example(output: Path, relative: str, lint_version: str) -> tuple[Path, set[str]]:
    """Remove only copied generated files in owned staging; source files stay intact."""
    if relative == "fixtures/primary_sdk_consumer":
        packages = ("dust_dart", "dust_db_sqlite3")
    elif relative == "examples/server_codegen":
        packages = ("dust_dart", "dust_server")
    elif relative in ("examples/benchmark_project", "fixtures/primary_flutter_consumer"):
        packages = ("dust_dart", "dust_flutter")
    else:
        packages = ("dust_dart",)
    app = stage_consumer(ROOT, output, relative, lint_version, packages=packages)
    analysis = (ROOT / "analysis_options.yaml").read_text(encoding="utf-8")
    if lint_version == "7.0.0":
        # Dart 3.6 does not recognize these already-disabled newer lint names.
        for rule in ("remove_deprecations_in_breaking_versions", "unnecessary_ignore"):
            analysis = analysis.replace(f"    {rule}: false\n", "")
    (output / "analysis_options.yaml").write_text(analysis, encoding="utf-8")
    generated = {path.relative_to(app).as_posix() for path in generated_files(app)}
    for name in generated:
        (app / name).unlink()
    return app, generated


def generated_files(app: Path) -> list[Path]:
    """Include legacy generated HTTP tests whose filenames do not end in .g.dart."""
    result = []
    for folder in ("lib", "test"):
        for path in (app / folder).rglob("*.dart"):
            source = path.read_text(encoding="utf-8")
            if path.name.endswith(".g.dart") or (
                source.startswith("// GENERATED CODE - DO NOT MODIFY BY HAND\n")
                and GENERATED_MARKER in source
            ):
                result.append(path)
    return sorted(result)


def generated_hashes(app: Path) -> dict[str, str]:
    """Record generated bytes and reject a successful command that emitted nothing."""
    result = {path.relative_to(app).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest()
              for path in generated_files(app)}
    if not result:
        raise ValueError("Dust produced no generated Dart files")
    return result


def require_deterministic_generation(rows: list[dict[str, object]]) -> None:
    """The same supported source must produce identical bytes on both SDK ends."""
    for target in ("dart", "flutter"):
        generated = [row["generated"] for row in rows if row["target"] == target]
        if len(generated) != 2 or generated[0] != generated[1]:
            raise ValueError(f"Missing or different minimum/latest {target} generated output")


def generated_library_coverage(report: Path, stems: tuple[str, ...]) -> dict[str, dict[str, int]]:
    """Require each expected generated library once, nonempty and completely hit."""
    result = {}
    for record in report.read_text().split("end_of_record"):
        lines = record.splitlines()
        names = [stem for stem in stems if any(
            line.startswith("SF:") and line.endswith(f"/{stem}.g.dart") for line in lines)]
        if not names:
            continue
        name, = names
        hits = [int(line.split(",")[1]) for line in lines if line.startswith("DA:")]
        if name in result or not hits or any(hit <= 0 for hit in hits):
            raise ValueError(f"Incomplete or duplicate generated coverage: {name}")
        result[name] = {"hit": len(hits), "found": len(hits)}
    if set(result) != set(stems):
        raise ValueError("Missing generated library coverage")
    return result
